{"content": "import { useQuery } from "@tanstack/react-query";
import { format, isToday } from "date-fns";
import { ArrowDown, ArrowUp, ChevronLeft, ChevronRight } from "lucide-react";
import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  CartesianGrid,
  LabelList,
  Line,
  LineChart,
  ReferenceArea,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";

import { cn } from "@/lib/utils";
import query from "@/Utils/request/query";
import { Code } from "@/types/base/code/code";
import { DiagnosticReportRead } from "@/types/emr/diagnosticReport/diagnosticReport";
import { ObservationListRead } from "@/types/emr/observation/observation";
import observationApi from "@/types/emr/observation/observationApi";

type ReadingStatus = "low" | "high" | "normal" | "na";

interface Reading {
  datetime: string;
  value: number | null;
  raw: string;
  status: ReadingStatus;
}

interface CodeSeries {
  code: Code;
  unit?: string;
  min?: number;
  max?: number;
  readings: Reading[];
}

const LINE_COLOR = "#0d9488"; // teal-600
const REF_BAND_COLOR = "#dbeafe"; // blue-100
const DATE_PAGE_SIZE = 7;

function readingStatus(
  value: number | null,
  min?: number,
  max?: number,
): ReadingStatus {
  if (value === null || Number.isNaN(value)) return "na";
  if (min !== undefined && value < min) return "low";
  if (max !== undefined && value > max) return "high";
  return "normal";
}

function formatDay(datetime: string, todayLabel: string): string {
  const date = new Date(datetime);
  return isToday(date) ? todayLabel : format(date, "dd MMM");
}

function buildSeries(group: {
  code: Code;
  results: ObservationListRead[];
}): CodeSeries {
  const sorted = [...group.results].sort(
    (a, b) =>
      new Date(a.effective_datetime).getTime() -
      new Date(b.effective_datetime).getTime(),
  );

  const range = sorted.find((o) => o.reference_range?.[0])?.reference_range?.[0];
  const unit = sorted.find((o) => o.value?.unit?.code)?.value?.unit?.code;

  const readings: Reading[] = sorted.map((observation) => {
    const raw = observation.value?.value ?? "";
    const numeric = Number(raw);
    const value = raw !== "" && !Number.isNaN(numeric) ? numeric : null;
    return {
      datetime: observation.effective_datetime,
      value,
      raw: String(raw),
      status: readingStatus(value, range?.min, range?.max),
    };
  });

  return {
    code: group.code,
    unit,
    min: range?.min,
    max: range?.max,
    readings,
  };
}

interface ObservationTrendSheetProps {
  children: React.ReactNode;
  patientId: string;
  encounterId?: string;
  diagnosticReport: DiagnosticReportRead;
}

export function ObservationTrendSheet({
  children,
  patientId,
  encounterId,
  diagnosticReport,
}: ObservationTrendSheetProps) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const [scope, setScope] = useState<"encounter" | "all">("encounter");
  const [activeCodeKey, setActiveCodeKey] = useState<string | undefined>(
    undefined,
  );
  const [abnormalOnly, setAbnormalOnly] = useState(false);
  const [datePage, setDatePage] = useState(0);

  const scopedEncounterId = encounterId ?? diagnosticReport.encounter?.id;

  // Each tab represents an observation (main_code) of the diagnostic report.
  const codes = useMemo(() => {
    const seen = new Set<string>();
    const result: Code[] = [];
    for (const observation of diagnosticReport.observations ?? []) {
      const code = observation.main_code;
      if (code && !seen.has(code.code)) {
        seen.add(code.code);
        result.push(code);
      }
    }
    return result;
  }, [diagnosticReport.observations]);

  // Graph/table data comes from the analyse API (same pattern as plots.tsx).
  const { data, isLoading } = useQuery({
    queryKey: [
      "observation-analyse",
      patientId,
      scope === "encounter" ? scopedEncounterId : "all",
      codes.map((c) => c.code).join(","),
    ],
    queryFn: query(observationApi.analyse, {
      pathParams: { patientId },
      queryParams:
        scope === "encounter" && scopedEncounterId
          ? { encounter: scopedEncounterId }
          : {},
      body: { codes },
    }),
    enabled: open && codes.length > 0,
  });

  const series = useMemo<CodeSeries[]>(
    () => (data?.results ?? []).map(buildSeries),
    [data],
  );

  const activeSeries =
    series.find((s) => s.code.code === activeCodeKey) ?? series[0];

  // All distinct datetimes across every code, newest first.
  const allDates = useMemo(() => {
    const set = new Set<string>();
    series.forEach((s) => s.readings.forEach((r) => set.add(r.datetime)));
    return Array.from(set).sort(
      (a, b) => new Date(b).getTime() - new Date(a).getTime(),
    );
  }, [series]);

  const reportTitle =
    diagnosticReport.service_request?.title ||
    diagnosticReport.code?.display ||
    t("diagnostic_report", { count: 1 });

  const dateRangeLabel =
    allDates.length > 0
      ? `${format(new Date(allDates[allDates.length - 1]), "dd MMM")} → ${format(
          new Date(allDates[0]),
          "dd MMM",
        )}`
      : "";

  // Chart data for the active code, oldest -> newest (left to right).
  const chartData = useMemo(() => {
    if (!activeSeries) return [];
    return activeSeries.readings
      .filter((r) => r.value !== null)
      .map((r) => ({
        label: formatDay(r.datetime, t("today")),
        value: r.value as number,
      }));
  }, [activeSeries, t]);

  const yDomain = useMemo<[number, number]>(() => {
    const candidates = chartData.map((d) => d.value);
    if (activeSeries?.min !== undefined) candidates.push(activeSeries.min);
    if (activeSeries?.max !== undefined) candidates.push(activeSeries.max);
    if (candidates.length === 0) return [0, 1];
    const lo = Math.min(...candidates);
    const hi = Math.max(...candidates);
    const pad = (hi - lo || 1) * 0.15;
    return [lo - pad, hi + pad];
  }, [chartData, activeSeries]);

  const latestValue = chartData.at(-1)?.value;

  // Table rows filtered by the abnormal-only toggle.
  const visibleSeries = abnormalOnly
    ? series.filter((s) =>
        s.readings.some((r) => r.status === "low" || r.status === "high"),
      )
    : series;

  const totalDatePages = Math.max(
    1,
    Math.ceil(allDates.length / DATE_PAGE_SIZE),
  );
  const clampedPage = Math.min(datePage, totalDatePages - 1);
  const pagedDates = allDates.slice(
    clampedPage * DATE_PAGE_SIZE,
    clampedPage * DATE_PAGE_SIZE + DATE_PAGE_SIZE,
  );

  const readingFor = (s: CodeSeries, datetime: string) =>
    s.readings.find((r) => r.datetime === datetime);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent className="max-w-4xl w-full p-0 gap-0 overflow-hidden">
        {/* Header */}
        <div className="px-6 pt-6 pb-4 border-b">
          <DialogTitle className="text-lg font-semibold">
            {reportTitle} · {t("all_results")}
          </DialogTitle>
          <p className="text-sm text-gray-500 mt-1">
            {scope === "encounter"
              ? t("current_encounter")
              : t("all_encounters")}
            {" · "}
            {t("recordings_count", { count: allDates.length })}
            {dateRangeLabel && ` · ${dateRangeLabel}`}
          </p>
        </div>

        <div className="px-6 py-4 space-y-4 max-h-[70vh] overflow-y-auto">
          {isLoading ? (
            <div className="space-y-3">
              <Skeleton className="h-6 w-48" />
              <Skeleton className="h-56 w-full" />
              <Skeleton className="h-40 w-full" />
            </div>
          ) : series.length === 0 ? (
            <div className="flex h-40 items-center justify-center text-gray-500">
              {t("no_data_available")}
            </div>
          ) : (
            <>
              {/* Trend title */}
              <h3 className="text-sm font-semibold">
                {activeSeries?.code.display} - {t("whole_trend")}
              </h3>

              {/* Tabs + scope toggle */}
              <div className="flex items-center justify-between gap-3 flex-wrap">
                <div className="flex items-center gap-1 rounded-md border p-1">
                  {series.map((s) => {
                    const isActive = s.code.code === activeSeries?.code.code;
                    return (
                      <button
                        key={s.code.code}
                        type="button"
                        onClick={() => setActiveCodeKey(s.code.code)}
                        className={cn(
                          "px-3 py-1 text-sm rounded transition-colors",
                          isActive
                            ? "bg-gray-100 font-medium text-gray-900"
                            : "text-gray-500 hover:text-gray-700",
                        )}
                      >
                        {s.code.display}
                      </button>
                    );
                  })}
                </div>

                <div className="flex items-center gap-1 rounded-md border p-1">
                  <button
                    type="button"
                    onClick={() => setScope("encounter")}
                    className={cn(
                      "px-3 py-1 text-sm rounded transition-colors",
                      scope === "encounter"
                        ? "bg-gray-100 font-medium text-gray-900"
                        : "text-gray-500 hover:text-gray-700",
                    )}
                  >
                    {t("this_encounter_short")}
                  </button>
                  <button
                    type="button"
                    onClick={() => setScope("all")}
                    className={cn(
                      "px-3 py-1 text-sm rounded transition-colors",
                      scope === "all"
                        ? "bg-gray-100 font-medium text-gray-900"
                        : "text-gray-500 hover:text-gray-700",
                    )}
                  >
                    {t("include_previous_short")}
                  </button>
                </div>
              </div>

              {/* Chart */}
              <div className="relative rounded-md border bg-white pt-6">
                {activeSeries?.min !== undefined &&
                  activeSeries?.max !== undefined && (
                    <span className="absolute left-3 top-2 text-xs text-gray-500">
                      {`(${t("ref")} ${activeSeries.min}-${activeSeries.max}${
                        activeSeries.unit ? ` ${activeSeries.unit}` : ""
                      })`}
                    </span>
                  )}
                <span className="absolute right-3 top-2 text-xs text-gray-400">
                  {t("newest")} →
                </span>
                <div className="h-64 w-full">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart
                      data={chartData}
                      margin={{ top: 24, right: 48, left: 12, bottom: 8 }}
                    >
                      <CartesianGrid vertical={false} stroke="#f1f5f9" />
                      {activeSeries?.min !== undefined &&
                        activeSeries?.max !== undefined && (
                          <ReferenceArea
                            y1={activeSeries.min}
                            y2={activeSeries.max}
                            fill={REF_BAND_COLOR}
                            fillOpacity={0.5}
                            ifOverflow="extendDomain"
                          />
                        )}
                      <XAxis
                        dataKey="label"
                        tick={{ fontSize: 12, fill: "#6b7280" }}
                        axisLine={false}
                        tickLine={false}
                      />
                      <YAxis hide domain={yDomain} />
                      <Tooltip
                        formatter={(value: number | string) => [
                          `${value}${
                            activeSeries?.unit ? ` ${activeSeries.unit}` : ""
                          }`,
                          activeSeries?.code.display ?? "",
                        ]}
                      />
                      <Line
                        type="monotone"
                        dataKey="value"
                        stroke={LINE_COLOR}
                        strokeWidth={2}
                        dot={{ r: 4, fill: LINE_COLOR, strokeWidth: 0 }}
                        activeDot={{ r: 5 }}
                        connectNulls
                      >
                        <LabelList
                          dataKey="value"
                          position="top"
                          className="fill-gray-600 text-xs"
                        />
                      </Line>
                    </LineChart>
                  </ResponsiveContainer>
                </div>
                {latestValue !== undefined && (
                  <span className="absolute right-3 bottom-8 text-xs font-medium text-gray-700">
                    {t("latest")} {latestValue}
                  </span>
                )}
              </div>

              {/* Table */}
              <div className="rounded-md border">
                <div className="flex items-center justify-between px-4 py-3 border-b">
                  <div className="flex items-center gap-2">
                    <span className="h-4 w-1 rounded bg-primary-600" />
                    <div>
                      <p className="text-sm font-semibold">
                        {reportTitle} (
                        {t("recordings_count", { count: allDates.length })})
                      </p>
                      <p className="text-xs text-gray-500">
                        {abnormalOnly
                          ? t("showing_abnormal_readings")
                          : t("showing_all_readings", {
                              count: allDates.length,
                            })}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    <label className="flex items-center gap-2 text-sm text-gray-600">
                      <Switch
                        checked={abnormalOnly}
                        onCheckedChange={setAbnormalOnly}
                      />
                      {t("abnormal_only")}
                    </label>
                    <div className="flex items-center gap-1">
                      <Button
                        variant="outline"
                        size="icon"
                        className="h-7 w-7"
                        disabled={clampedPage === 0}
                        onClick={() => setDatePage((p) => Math.max(0, p - 1))}
                      >
                        <ChevronLeft className="size-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="icon"
                        className="h-7 w-7"
                        disabled={clampedPage >= totalDatePages - 1}
                        onClick={() =>
                          setDatePage((p) => Math.min(totalDatePages - 1, p + 1))
                        }
                      >
                        <ChevronRight className="size-4" />
                      </Button>
                    </div>
                  </div>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="text-gray-500">
                        <th className="text-left font-medium px-4 py-2 sticky left-0 bg-white">
                          {t("component")}
                        </th>
                        {pagedDates.map((d) => (
                          <th
                            key={d}
                            className="text-right font-medium px-4 py-2 whitespace-nowrap"
                          >
                            {formatDay(d, t("today"))}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {visibleSeries.map((s) => {
                        const isActive =
                          s.code.code === activeSeries?.code.code;
                        return (
                          <tr
                            key={s.code.code}
                            onClick={() => setActiveCodeKey(s.code.code)}
                            className={cn(
                              "cursor-pointer border-t",
                              isActive && "bg-primary-50/50",
                            )}
                          >
                            <td
                              className={cn(
                                "px-4 py-2 sticky left-0 bg-white",
                                isActive && "bg-primary-50/50",
                              )}
                            >
                              <span className="font-medium">
                                {s.code.display}
                              </span>
                              {s.min !== undefined && s.max !== undefined && (
                                <span className="text-gray-400 ml-2 whitespace-nowrap">
                                  ({s.min} – {s.max}
                                  {s.unit ? ` ${s.unit}` : ""})
                                </span>
                              )}
                            </td>
                            {pagedDates.map((d) => {
                              const reading = readingFor(s, d);
                              const status = reading?.status ?? "na";
                              const abnormal =
                                status === "low" || status === "high";
                              return (
                                <td
                                  key={d}
                                  className={cn(
                                    "px-4 py-2 text-right whitespace-nowrap",
                                    abnormal &&
                                      "bg-orange-50 text-orange-700 font-medium",
                                  )}
                                >
                                  {reading ? (
                                    <span className="inline-flex items-center justify-end gap-1">
                                      {reading.raw}
                                      {status === "low" && (
                                        <ArrowDown className="size-3" />
                                      )}
                                      {status === "high" && (
                                        <ArrowUp className="size-3" />
                                      )}
                                    </span>
                                  ) : (
                                    <span className="text-gray-300">–</span>
                                  )}
                                </td>
                              );
                            })}
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            </>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}
