              </h3>

              {/* Tabs + scope toggle */}
              <div className="flex items-center justify-between gap-3 flex-wrap">
                <div className="flex items-center gap-1 rounded-md border p-1">
                  {series.map((s) => {
                    const isActive = s.code.code === activeSeries?.code.code;
                    return (
                      <button
