  "#2563eb", // blue-600
  "#dc2626", // red-600
  "#16a34a", // green-600
  "#ea580c", // orange-600
  "#9333ea", // purple-600
  "#0d9488", // teal-600
] as const;

const formatChartDate = (
  dateString: string,
): { display: string; time: number } => {
  const date = new Date(dateString);
  const hours = date.getHours().toString().padStart(2, "0");
  const minutes = date.getMinutes().toString().padStart(2, "0");
  const day = date.getDate().toString().padStart(2, "0");
  const month = (date.getMonth() + 1).toString().padStart(2, "0");
  const year = date.getFullYear();
  return {
    display: `${hours}:${minutes} ${day}/${month}/${year}`,
    time: date.getTime(),
  };
};

const ObservationHistoryGraph = ({
  observation,
  patientId,
  encounterId,
}: {
  observation: ObservationRead;
  patientId: string;
  encounterId: string;
}) => {
  const { t } = useTranslation();

  const { data, isLoading } = useQuery({
    queryKey: ["observations", patientId, encounterId, observation.main_code],

    queryFn: query(observationApi.analyse, {
      pathParams: { patientId: patientId },
      queryParams: {
        encounter: encounterId,
      },
      body: {
        codes: observation.main_code ? [observation.main_code] : [],
      },
    }),
    enabled: observation.main_code !== undefined,
  });

  if (isLoading || !data) {
    return <Loading />;
  }

  const label = observation.main_code?.display || t("observation");

  const resultGroup = data.results.find(
    (rg) => rg.code.code === observation.main_code?.code,
  );

  const chartData = (resultGroup?.results ?? [])
    .map((obs) => {
      if (!obs.effective_datetime) return null;
      const value = Number(obs.value?.value);
      if (isNaN(value)) return null;
      const { display, time } = formatChartDate(obs.effective_datetime);
      return { timestamp: display, time, [label]: value };
    })
    .filter((entry): entry is NonNullable<typeof entry> => entry !== null)
    .sort((a, b) => a.time - b.time);

