const ObservationHistoryTable = ({
  observations,
  patientId,
  encounterId,
}: {
  observations: ObservationRead[];
  patientId: string;
  encounterId: string;
}) => {
  const { t } = useTranslation();

  const codes = observations
    .map((obs) => obs.main_code)
    .filter((code): code is NonNullable<typeof code> => code != null);

  const { data, isLoading } = useQuery({
    queryKey: [
      "observations-table",
      patientId,
      encounterId,
      codes.map((c) => c.code),
    ],
    queryFn: query(observationApi.analyse, {
      pathParams: { patientId },
      queryParams: { encounter: encounterId },
      body: { codes },
    }),
    enabled: codes.length > 0,
  });

  if (isLoading || !data) {
    return <Loading />;
  }

  // Collect all unique effective dates across all observation groups.
  const dateSet = new Set<string>();
  for (const group of data.results) {
    for (const result of group.results) {
      if (result.effective_datetime) {
        dateSet.add(new Date(result.effective_datetime).toISOString());
      }
    }
  }

  // Most recent date first.
  const dates = Array.from(dateSet).sort(
    (a, b) => new Date(b).getTime() - new Date(a).getTime(),
  );

  if (dates.length === 0) {
    return (
      <div className="flex h-24 items-center justify-center text-sm text-gray-500">
        {t("no_data_available")}
      </div>
    );
  }

  const rows = observations.map((obs) => {
    const group = data.results.find(
      (rg) => rg.code.code === obs.main_code?.code,
    );

    const valuesByDate = new Map<
      string,
      { value?: string | null; interpretation?: Interpretation }
    >();
    for (const result of group?.results ?? []) {
      if (!result.effective_datetime) continue;
      const key = new Date(result.effective_datetime).toISOString();
      valuesByDate.set(key, {
        value: result.value?.value,
        interpretation: result.interpretation,
      });
    }

    const unit = obs.value?.unit?.display || obs.value?.unit?.code || "";
    const refRange = obs.reference_range?.[0];

    return {
      id: obs.id,
      title: obs.observation_definition?.title || t("observation"),
      unit,
      refMin: refRange?.min,
      refMax: refRange?.max,
      valuesByDate,
    };
  });

  return (
    <div className="overflow-x-auto rounded-lg border">
      <Table>
        <TableHeader>
          <TableRow className="bg-gray-50">
            <TableHead className="sticky left-0 z-10 bg-gray-50">
              {t("component")}
            </TableHead>
            {dates.map((date) => (
              <TableHead
                key={date}
                className="whitespace-nowrap text-center font-normal"
              >
                {isToday(new Date(date))
                  ? t("today")
                  : format(new Date(date), "d MMM")}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.id}>
              <TableCell className="sticky left-0 z-10 bg-white">
                <div className="font-medium">{row.title}</div>
                {(row.refMin != null || row.refMax != null) && (
                  <div className="text-xs text-gray-500">
                    ({row.refMin ?? "-"} - {row.refMax ?? "-"}
                    {row.unit ? ` ${row.unit}` : ""})
                  </div>
                )}
              </TableCell>
              {dates.map((date) => {
                const entry = row.valuesByDate.get(date);
                const highlight = entry?.interpretation?.highlight;
                return (
                  <TableCell
                    key={date}
                    className={cn(
                      "whitespace-nowrap text-center",
                      highlight && "bg-orange-50 font-medium text-orange-700",
                    )}
                  >
                    {entry?.value ?? "-"}
                  </TableCell>
                );
              })}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
};"}

