      // succeeds so a failed observation save doesn't leave the report
      // updated with stale observations.
      const reportUpdate = {
        id: report.id,
        status: report.status,
        category: report.category,
        code: report.code,
        note: report.note,
        conclusion,
      };

      if (formattedObservations.length > 0) {
        upsertObservations(
          {
            observations: formattedObservations,
          },
          {
            onSuccess: () => updateDiagnosticReport(reportUpdate),
          },
